INSERT INTO "workflow_template" ("id", "name", "description", "category", "minPlan", "published", "nodes", "connections", "nodeTypes", "useCount", "createdById", "createdAt", "updatedAt")
VALUES ('tpl_invoice_to_google_sheets', 'Invoice to Google Sheets', 'Upload an invoice (a photo, a scan or a PDF) on a form; a vision model reads the vendor, number, dates and amounts, and a row is added to a Google Sheet. To set it up: pick a credential on the Gemini node (or connect another vision model), and choose your Google credential and spreadsheet on the Google Sheets node. The sheet''s columns are: Vendor, Invoice number, Invoice date, Due date, Currency, Subtotal, Tax, Total, File name. Activate the workflow and open the Form Trigger''s Form URL.', 'Documents', 'FREE', true, '[{"id":"tpl_inv_form","type":"FORM_TRIGGER","position":{"x":0,"y":0},"data":{"formTitle":"Upload an invoice","formDescription":"A photo, a scan or a PDF of the invoice.","formFields":"[{\"label\":\"Invoice\",\"type\":\"file\",\"required\":true,\"options\":\"\"}]","submitLabel":"Upload","afterSubmit":"message","thankYouMessage":"Thank you. The invoice was received."}},{"id":"tpl_inv_model","type":"GEMINI","position":{"x":260,"y":220},"data":{"variableName":"visionModel"}},{"id":"tpl_inv_analyze","type":"ANALYZE_DOCUMENT","position":{"x":320,"y":0},"data":{"variableName":"invoice","operation":"extract_fields","file":"form.invoice","attributes":"vendor: the company that issued the invoice\ninvoiceNumber\ninvoiceDate (date)\ndueDate (date)\ncurrency: three-letter code such as USD or PKR\nsubtotal (number): the amount before tax\ntax (number)\ntotal (number): the amount to pay","maxPages":"3"}},{"id":"tpl_inv_sheet","type":"GOOGLE_SHEETS","position":{"x":640,"y":0},"data":{"variableName":"sheetRow","sheetName":"Sheet1","rowData":"{{invoice.output.vendor}}, {{invoice.output.invoiceNumber}}, {{invoice.output.invoiceDate}}, {{invoice.output.dueDate}}, {{invoice.output.currency}}, {{invoice.output.subtotal}}, {{invoice.output.tax}}, {{invoice.output.total}}, {{form.invoice.fileName}}"}}]'::jsonb, '[{"fromNodeId":"tpl_inv_form","toNodeId":"tpl_inv_analyze","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_inv_model","toNodeId":"tpl_inv_analyze","fromOutput":"source-1","toInput":"sub-model"},{"fromNodeId":"tpl_inv_analyze","toNodeId":"tpl_inv_sheet","fromOutput":"source-1","toInput":"target-1"}]'::jsonb, ARRAY['FORM_TRIGGER', 'GEMINI', 'ANALYZE_DOCUMENT', 'GOOGLE_SHEETS']::text[], 0, 'system', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "workflow_template" ("id", "name", "description", "category", "minPlan", "published", "nodes", "connections", "nodeTypes", "useCount", "createdById", "createdAt", "updatedAt")
VALUES ('tpl_cv_screening_score_and_email', 'CV screening: score and email', 'A candidate uploads their CV on a form; a vision model reads it (scanned CVs too), a second step scores it from 0 to 100 against your job description, and the result is emailed to you. To set it up: pick a credential on the Gemini node (or connect another vision model), replace the job description in the Information Extractor''s System Prompt, and choose an SMTP credential and your address on the Email node. The score is a first look to help you sort applications, not a decision: read the CV before you reject anyone.', 'Documents', 'FREE', true, '[{"id":"tpl_cv_form","type":"FORM_TRIGGER","position":{"x":0,"y":0},"data":{"formTitle":"Apply for the job","formDescription":"Upload your CV as a PDF or an image.","formFields":"[{\"label\":\"Full name\",\"type\":\"text\",\"required\":true,\"options\":\"\"},{\"label\":\"Email\",\"type\":\"email\",\"required\":true,\"options\":\"\"},{\"label\":\"CV\",\"type\":\"file\",\"required\":true,\"options\":\"\"}]","submitLabel":"Send application","afterSubmit":"message","thankYouMessage":"Thank you. We received your application."}},{"id":"tpl_cv_model","type":"GEMINI","position":{"x":420,"y":220},"data":{"variableName":"visionModel"}},{"id":"tpl_cv_analyze","type":"ANALYZE_DOCUMENT","position":{"x":320,"y":0},"data":{"variableName":"cv","operation":"extract_text","file":"form.cv","maxPages":"5"}},{"id":"tpl_cv_score","type":"INFORMATION_EXTRACTOR","position":{"x":640,"y":0},"data":{"variableName":"screening","inputText":"{{cv.text}}","attributes":"score (number): 0 to 100, how well the CV fits the job described in the instructions\nyearsOfExperience (number): years of relevant work experience\nkeySkills (list): the skills that matter for this job\nstrengths: one or two sentences\nconcerns: one or two sentences, or none\nrecommendation: one of interview, maybe, reject","systemPrompt":"You screen CVs for the job below. Judge only on what the CV says about skills and experience. Ignore name, gender, age, religion, photo and address.\n\nJob: Customer support agent. Required: two or more years in customer support, good written English, experience with a help desk tool. Nice to have: Urdu, e-commerce experience.\n\n(Replace this job description with your own.)"}},{"id":"tpl_cv_email","type":"EMAIL_SEND","position":{"x":960,"y":0},"data":{"recipient":"hiring@example.com","subject":"CV screening: {{form.full_name}} scored {{screening.output.score}}","body":"<p><strong>{{form.full_name}}</strong> ({{form.email}}) applied.</p>\n<p>Score: <strong>{{screening.output.score}}</strong> / 100<br>\nRecommendation: {{screening.output.recommendation}}<br>\nExperience: {{screening.output.yearsOfExperience}} years<br>\nKey skills: {{screening.output.keySkills}}</p>\n<p>Strengths: {{screening.output.strengths}}</p>\n<p>Concerns: {{screening.output.concerns}}</p>\n<p>The score is a first look made by a model. Read the attached CV before you decide.</p>","attachments":"form.cv"}}]'::jsonb, '[{"fromNodeId":"tpl_cv_form","toNodeId":"tpl_cv_analyze","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_cv_model","toNodeId":"tpl_cv_analyze","fromOutput":"source-1","toInput":"sub-model"},{"fromNodeId":"tpl_cv_analyze","toNodeId":"tpl_cv_score","fromOutput":"source-1","toInput":"target-1"},{"fromNodeId":"tpl_cv_model","toNodeId":"tpl_cv_score","fromOutput":"source-1","toInput":"sub-model"},{"fromNodeId":"tpl_cv_score","toNodeId":"tpl_cv_email","fromOutput":"source-1","toInput":"target-1"}]'::jsonb, ARRAY['FORM_TRIGGER', 'GEMINI', 'ANALYZE_DOCUMENT', 'INFORMATION_EXTRACTOR', 'EMAIL_SEND']::text[], 0, 'system', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
